<div class="proma-repair">
  <header class="pr-hero"><span class="pr-hero-icon"><i data-feather="shield"></i></span><div class="pr-hero-copy"><small>Append-only activity history</small><h2>گزارش ممیزی تعمیرات</h2><p>رویدادهای این ماژول برای پیگیری و حسابرسی نگهداری می‌شوند.</p></div></header>
  <section class="pr-card"><?php if (!$events): ?><div class="pr-empty">رویدادی ثبت نشده است.</div><?php else: ?><div class="pr-table-wrap"><table class="pr-table"><thead><tr><th scope="col">زمان</th><th scope="col">پرونده</th><th scope="col">رویداد</th><th scope="col">کاربر</th><th scope="col">IP</th><th scope="col">جزئیات</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td data-label="زمان"><?= e(jdatetime($event['created_at'])) ?></td><td data-label="پرونده"><?php if (!empty($event['repair_id'])): ?><a href="<?= e(url('plugin/repair/detail/' . (int) $event['repair_id'])) ?>"><span class="pr-code"><?= e($event['tracking_code'] ?? ('#' . $event['repair_id'])) ?></span></a><?php endif; ?></td><td data-label="رویداد"><?= e($event['action']) ?></td><td data-label="کاربر"><?= e($event['full_name'] ?: 'سامانه') ?></td><td data-label="IP"><span class="pr-code"><?= e($event['ip_address'] ?: '—') ?></span></td><td data-label="جزئیات"><small><?= e($event['details'] ?? '') ?></small></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div>
